implementation.operation:
{
    // ADAPT: the business types to check (role carriers, master data, parts).
    types = [
        `app.core:Order`,
        `app.core:OrderItem`,
        `app.master:Supplier`
    ];
    check = type -> {
        objs = all($type);
        {
            "type": $type.label(),
            "count": $objs.size(),
            "canRead": $objs.filter(o -> canRead($o)).size(),
            "canWrite": $objs.filter(o -> canWrite($o)).size(),
            "canDelete": $objs.filter(o -> canDelete($o)).size(),
            "samples": ($objs.size() > 10 ? $objs.subList(0, 10) : $objs).map(o -> $o.label())
        }
    };
    {
        "user": currentUser().toString(),
        "types": $types.map(t -> $check($t))
    }
}

{
    // ADAPT: the types to check. Needs Read on tl.model (access parent on tl.model:TLModelPart).
    types = [
        `app.core:Order`,
        `app.master:Supplier`
    ];
    parts = type -> $type.get(`tl.model:TLStructuredType#localParts`)
        .union($type.get(`tl.model:TLClass#generalizations`).flatMap(g -> $g.get(`tl.model:TLStructuredType#localParts`)));
    check = type -> {
        first = all($type).firstElement();
        {
            "type": $type.label(),
            "first": $first == null ? null : $first.label(),
            "notReadable": $first == null ? [] : $parts($type)
                .filter(p -> !canReadAttribute($first, $p))
                .map(p -> $p.get(`tl.model:TLNamedPart#name`)),
            "notWritable": $first == null ? [] : $parts($type)
                .filter(p -> !canWriteAttribute($first, $p))
                .map(p -> $p.get(`tl.model:TLNamedPart#name`))
        }
    };
    {
        "user": currentUser().toString(),
        "types": $types.map(t -> $check($t))
    }
}

{
    log = changeLog(maxEntries: 500);
    changes = $log.flatMap(cs -> $cs.get(`tl.changelog:ChangeSet#changes`));
    updates = $changes.filter(c -> $c.instanceOf(`tl.changelog:Update`));
    // changed object filtered away by object security (or deleted meanwhile)
    hidden = $updates.filter(u -> $u.get(`tl.changelog:Change#object`) == null);
    mods = $hidden.flatMap(u -> $u.get(`tl.changelog:Update#modifications`));
    describe = m -> "{0}: {1} -> {2}".fill(
        $m.get(`tl.changelog:Modification#part`).toString(),
        $m.get(`tl.changelog:Modification#oldValue`).toString(),
        $m.get(`tl.changelog:Modification#newValue`).toString());
    samples = $mods.size() > 30 ? $mods.subList(0, 30) : $mods;
    {
        "user": currentUser().toString(),
        "changeSets": $log.size(),
        "changes": $changes.size(),
        "updatesOnObjectsNotVisible": $hidden.size(),
        "samples": $samples.map(m -> $describe($m))
    }
}
